def cb012840(func):
    @wraps(func)
    def wrapper(self, *args, **kwargs):
        try:
            return func(self, *args, **kwargs)
        except ApiException as e:
            if "No API found with those values API" in e.body:
                raise NotImplementedError("This keyword was affected by changes implemented with CB012840 "
                                          "and is no longer usable. Please use keywords 'perform_commissioning and "
                                          "'perform_delta_recommissioning' to commission/recommission.")
            else:
                raise e

    return wrapper


