    def search_parameter_of_current_plan(self, mo_dn, para_name, timeout=30):
        try:
            return self.asm_v1.search_parameter_of_current_plan(mo_dn=mo_dn, para_name=para_name, timeout=timeout)

        except ApiException as e:
            if "No API found with those values API" in e.body:
                return self._get_parameter_for_given_managed_object(
                    response=self.emservice_v1.search_parameter_of_current_plan(para_name=para_name, timeout=timeout),
                    mo_dn=mo_dn,
                    parameter_name=para_name
                )
            else:
                raise e

    def _get_parameter_for_given_managed_object(self, response, mo_dn, parameter_name):
        main_parameter_name = parameter_name.split("/")[0]
        main_parameter = True if len(parameter_name.split("/")) == 1 else False

        for item in response["items"]:
            if item["distname"] == mo_dn and item["parameterName"] == main_parameter_name:
                if main_parameter:
                    return self._get_current_value_of_main_parameter(item)
                else:
                     return self._get_current_value_of_parameter_in_the_structure(item=item, para_name=parameter_name)

        raise ValueError(f"Parameter {parameter_name} for managed object {mo_dn} not found in the current plan.")

    @staticmethod
    def _get_current_value_of_main_parameter(item):
        """
        If user gives only main_parameter_name of the complex parameter, this function will be called.
        Therefore, it is needed to check if the given parameter is a list of other parameters or a single value.
        """
        parameter_value = json.loads(item["parameter"]["value"])
        try:
            if isinstance(parameter_value, list) and isinstance(parameter_value[0], list):
                return parameter_value

            return parameter_value["currentValue"]

        except TypeError:
            return [element["currentValue"] for element in parameter_value]

    @staticmethod
    def _get_current_value_of_parameter_in_the_structure(item, para_name):
        """
        If user gives only main_parameter_name and index, function will return whole object from given index.
        Otherwise, it will return the value of the parameter with the given name.
        """
        parameter_info = json.loads(item["parameter"]["value"])
        index = int(para_name.split("/")[1])

        if len(para_name.split("/")) == 2 and isinstance(parameter_info[index], list):
            return parameter_info[index]

        name = para_name.split("/")[2]
        for structure_index, structure_values in enumerate(parameter_info):
            if structure_index == index:
                for element in structure_values:
                    if element["name"] == name:
                        return json.loads(element["value"])["currentValue"]

    def get_rnicmods_diff(self, timeout=30):
        return self.emservice_v1.get_rnicmods_diff(timeout=timeout)

    def get_gnss_info(self, timeout=30):
        try:
            gnsses_info = self.emservice_v1.get_rnicmods_diff(timeout=timeout)['created']
        except KeyError:
            return []

        result = []

        for i in range(len(gnsses_info)):
            if "gnsses" in gnsses_info[i]:
                result.append({
                    "rNICModRId": gnsses_info[i]["rNICModRId"],
                    "configDN": gnsses_info[i]["configDN"],
                    "gnsses": gnsses_info[i]["gnsses"]
                })

        return result

    def validate_plan(self, plan_id, timeout=30, wait_for_completion=False, raw=False):
        try:
            plan_validation_info = self.asm_v1.validate_plan(plan_id=plan_id,
                                                             timeout=timeout,
                                                             wait_for_completion=wait_for_completion)
            return PlanValidationASMV1.from_object_dict(plan_validation_info)

        except ApiException as e:
            if "No API found with those values API" in e.body:
                response = self.emservice_v1.validate_plan(plan_id=plan_id, timeout=timeout,
                                                                       wait_for_completion=wait_for_completion)
                return response if raw else PlanValidationEMSERVICEv1.from_object_dict(response)
            else:
                raise e

