    def get_staged_plan_validation_results(self, plan_id, validation_id, error_type=None):
        try:
            validation_results = self.asm_v1.get_staged_plan_validation_results(plan_id=plan_id,
                                                                                validation_id=validation_id,
                                                                                error_type=error_type)
            dict_results = StagedPlanValidationResultsASMV1.from_object_dict(validation_results)

            if error_type:
                return {error_type: dict_results[error_type], 'total': dict_results['total']}

            return dict_results

        except ApiException as e:
            if "No API found with those values API" in e.body:

                if error_type and error_type not in ["definitionError", "relationError"]:
                    raise ValueError(f"Error type {error_type} is not supported for the newer SW builds,"
                                     f" please use 'definitionError' or 'relationError'")

                return self.emservice_v1.get_staged_plan_validation_results(plan_id, validation_id, error_type)

            else:
                raise e

